import re

with open('doc/budget.md', 'r') as f:
    content = f.read()

# Get all budget-to-event links
links = {}
for name in ['6.1', '6.2', '6.3']:
    section = re.search(rf'### Sub-Section 6\.{name}:.*?(?=### Sub-Section 6\.|\Z)', content, re.DOTALL)
    if not section:
        continue
    text = section.group(0)
    for line in text.split('\n'):
        if 'budget' in line.lower() or 'record' in line.lower() or 'linked' in line.lower():
            codes = re.findall(r'rec[A-Za-z0-9]{15,}', line)
            if len(codes) >= 2 and codes[0] != codes[1]:
                links[codes[0]] = codes[1]

# Find Advertisement budgets with their event links
print("=== Advertisement budgets ===")
adv_info = []
for part in re.split(r'(?=### )', content):
    if 'Advertisement' in part:
        codes = re.findall(r'rec[A-Za-z0-9]{15,}', part)
        if codes:
            budget = codes[0]
            event = links.get(budget, 'No link')
            print(f"Budget: {budget}")
            print(f"Event: {event}")
            print(f"Part preview: {part[:600]}")
            if event in ['recykdvf4LgsyA3wZ', 'recggMW2eyCYceNcy']:
                print(f"*** TARGET: {event}")
                # Find numbers in this part
                nums = re.findall(r'\d+', part)
                print(f"Numbers: {nums[:15]}")
            print("---")
            adv_info.append((budget, event, part))

print(f"\nTotal links: {len(links)}")
print("\n=== Target event links ===")
for budget, event in links.items():
    if event in ['recykdvf4LgsyA3wZ', 'recggMW2eyCYceNcy']:
        print(f"{budget} -> {event}")

